+beforeEach(async () => {
+  testDir = await fs.mkdtemp(path.join(os.tmpdir(), "cx-notes-cmd-"));
+  await fs.mkdir(path.join(testDir, "notes"));
+  origCwd = process.cwd();
+  process.chdir(testDir);
+});
